fun {Label P : Type} [NormedAddCommGroup P] [NormedSpace ℝ P]
    {D : NavierStokes.PhaseJetBounds.Domain (Label × ℕ) NavierStokes.ScaledActualParticularControl.Slow}
    (s : NavierStokes.WeightedClasses.StripData P) (F : NavierStokes.PrimaryPulseBounds.PhaseConstruction D)
    (χ : P →L[ℝ] NavierStokes.ScaledActualParticularControl.Slow)
    (φ :
      Label × ℕ → NavierStokes.ScaledActualParticularControl.Slow →L[ℝ] NavierStokes.ScaledActualParticularControl.Slow)
    (clock normal : NavierStokes.ActualSignedControl.PositiveScale Label)
    (reference : Label → ℕ → NavierStokes.CommonCoverSolve.Geometry) (gap : Label → ℕ → ℕ) (r : Label → ℕ → ℝ)
    {A B C : ℝ} {a : ℕ} (hA : 1 ≤ A) (hB : 1 ≤ B) (hC : 1 ≤ C) (hφ : ∀ (i : Label × ℕ), ‖φ i‖ ≤ A)
    (hscale : ∀ (i : Label × ℕ), D.scale i ≤ B * s.slow i.2)
    (hsep : ∀ (l : Label) (n : ℕ), NavierStokes.WaveEnvelopeTransport.Separated (reference l n) (r l n) (F.L (l, n)))
    (hgeometry :
      ∀ (l : Label) (n : ℕ),
        NavierStokes.CommonCoverClass.argumentCost
            (NavierStokes.ScaledActualParticularControl.geometry reference gap clock l n) ≤
          C * s.slow n ^ a)
    (j : ℤ) (hj : j ≠ 0) {α : ℝ}
    (f : Label → ℕ → P × NavierStokes.ScaledActualParticularControl.Plane → NavierStokes.ProblemStatement.Space)
    (hf :
      NavierStokes.LabelSumBounds.UniformWaveClass (NavierStokes.CommonCoverClass.sourceStrip s)
        (NavierStokes.ActualParticularControl.groupedEnvelope
          (NavierStokes.ScaledActualParticularControl.geometry reference gap clock) r
          (NavierStokes.ScaledActualParticularControl.length F clock)
          (NavierStokes.ScaledActualParticularControl.envelope F clock))
        α f) =>
  let g := NavierStokes.ScaledActualParticularControl.geometry reference gap clock;
  let Lc := F.M * B / clock.lower;
  let K := Lc + Real.exp ((F.E + 4 * F.C) * F.M) + C + 1;
  have hLc := ⋯;
  have hK := ⋯;
  have hCK := ⋯;
  have hLK := ⋯;
  have heK := ⋯;
  have hd := ⋯;
  have hcopy := ⋯;
  have hsource := ⋯;
  have hlength := ⋯;
  have hsepTarget := ⋯;
  have herror := ⋯;
  { neighborhood := NavierStokes.ScaledActualParticularControl.neighborhood s F χ φ clock g, open_neighborhood := ⋯,
    contains := ⋯,
    interval := fun (l : Label) (n : ℕ) => NavierStokes.ScaledActualParticularControl.interval F clock (l, n),
    open_interval := ⋯, length_pos := ⋯, contains_interval := ⋯, bridge := ⋯, coefficient_smooth := ⋯,
    forcing_smooth := ⋯, columns_smooth := ⋯, current_slot := ⋯,
    rate := fun (l : Label) (n : ℕ) (v : ℝ) =>
      clock.value l n *
        NavierStokes.GaussianEnvelope.referenceRate (F.lam (l, n)) (F.u (l, n)) (F.L (l, n)) (clock.value l n * v),
    envelope_pos := ⋯, envelope_deriv := ⋯,
    errorRate := fun (l : Label) (n : ℕ) => clock.value l n * ((F.E + 4 * F.C) / D.scale (l, n)), errorRate_nonneg := ⋯,
    constant := K, constant_ge_one := hK, coordinate_power := a, length_bound := ⋯, exponential_bound := ⋯,
    coordinate_bound := ⋯, energy := ⋯, input_jets := ⋯ }
